import{_ as a,o,c as t,N as i}from"./chunks/framework.11ad0a06.js";const h=JSON.parse('{"title":"What Are Micro-Frontends?","description":"","frontmatter":{"sidebarDepth":2},"headers":[],"relativePath":"en/guide/index.md","lastUpdated":1795525255000}'),n={name:"en/guide/index.md"};function s(r,e,p,l,c,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="what-are-micro-frontends" tabindex="-1">What Are Micro-Frontends? <a class="header-anchor" href="#what-are-micro-frontends" aria-label="Permalink to &quot;What Are Micro-Frontends?&quot;">​</a></h1><p>Micro-frontends are an architectural approach and set of strategies that enable multiple teams to collaboratively build modern web applications by shipping features independently.</p><div class="tip custom-block"><p class="custom-block-title">Quote</p><p>Techniques, strategies and recipes for building a modern web app with multiple teams that can ship features independently. — <a href="https://micro-frontends.org/" target="_blank" rel="noreferrer">Micro Frontends</a></p></div><p>In simple terms, micro-frontends allow one web application to run another web application independently inside it.</p><p>What are typical use cases for micro-frontends?</p><div class="tip custom-block"><p class="custom-block-title">Examples</p><ul><li><p>Building an enterprise management portal that integrates existing procurement and finance systems into one unified platform.</p></li><li><p>Splitting a large monolithic application into smaller, independently developed and deployed applications to reduce maintenance overhead, then composing them within a host shell.</p></li><li><p>Adopting a new framework incrementally — for example, developing a standalone module in <code>React</code> inside a <code>Vue</code> application, deploying it independently, and mounting it back into the host app.</p></li></ul></div><p>What capabilities should a complete micro-frontend framework provide?</p><div class="tip custom-block"><p class="custom-block-title">Capabilities</p><ul><li><p><strong>Loading and unmounting sub-apps</strong></p><p>As users navigate between sub-apps, the framework must reliably load, render, and switch between them.</p></li><li><p><strong>Isolated runtime execution</strong></p><p>Sub-apps should not pollute the global <code>window</code> object or leak CSS styles into other applications; both JS and CSS must be effectively isolated.</p></li><li><p><strong>Sub-app route persistence</strong></p><p>Once a sub-app is active, browser refresh, forward, and back navigation must all work seamlessly with the sub-app&#39;s routing.</p></li><li><p><strong>Cross-app communication</strong></p><p>Applications should be able to communicate cleanly and conveniently.</p></li></ul></div><p>What are the benefits of adopting micro-frontends? (<a href="https://qiankun.umijs.org/guide" target="_blank" rel="noreferrer">Reference: qiankun</a>)</p><div class="tip custom-block"><p class="custom-block-title">Benefits</p><ul><li><p><strong>Technology stack agnostic</strong></p><p>The main framework imposes no restrictions on the tech stacks used by sub-apps, giving each team full autonomy.</p></li><li><p><strong>Independent development and deployment</strong></p><p>Each micro-app lives in its own repository and can be developed and deployed independently; the host app picks up updates automatically.</p></li><li><p><strong>Incremental upgrades</strong></p><p>Rewriting a large legacy system all at once is rarely feasible. Micro-frontends provide a practical strategy for gradual refactoring and migration.</p></li><li><p><strong>Isolated runtime</strong></p><p>Each micro-app maintains its own isolated runtime state without unintended state sharing.</p></li></ul></div><p>You might wonder: why not just use a plain <code>iframe</code>?</p><h2 id="the-iframe-approach" tabindex="-1">The iframe Approach <a class="header-anchor" href="#the-iframe-approach" aria-label="Permalink to &quot;The iframe Approach&quot;">​</a></h2><p>Using plain <code>iframe</code>s can indeed achieve micro-frontends, and its advantages are clear:</p><div class="tip custom-block"><p class="custom-block-title">Pros</p><ul><li>Extremely simple to use with zero cognitive overhead.</li><li>Near-perfect isolation: JavaScript, CSS, and DOM are completely separated between web applications.</li></ul></div><p>However, because the isolation is <strong>too strict</strong>, its drawbacks are equally pronounced:</p><div class="danger custom-block"><p class="custom-block-title">Cons</p><ul><li>Route state is lost on reload — refreshing the page resets the <code>iframe</code>&#39;s URL.</li><li>Severe DOM fragmentation — modals, popovers, and overlays are trapped inside the <code>iframe</code> and cannot cover the full viewport.</li><li>Cross-app communication is cumbersome.</li><li>Long blank-screen load times on every open, which is unacceptable for <a href="https://en.wikipedia.org/wiki/Single-page_application" target="_blank" rel="noreferrer">SPA applications</a>.</li></ul></div><h2 id="the-single-spa-approach" tabindex="-1">The single-spa Approach <a class="header-anchor" href="#the-single-spa-approach" aria-label="Permalink to &quot;The single-spa Approach&quot;">​</a></h2><p><a href="https://single-spa.js.org/docs/getting-started-overview" target="_blank" rel="noreferrer">single-spa</a> is a widely adopted micro-frontend solution whose core workflow is:</p><ul><li>Pre-register sub-apps (activation routes, entry resources, and lifecycle hooks).</li><li>Listen for route changes, load matching sub-app assets, invoke lifecycle hooks sequentially, and mount into the target container.</li></ul><p><a href="https://qiankun.umijs.org/guide" target="_blank" rel="noreferrer">qiankun</a> builds on <code>single-spa</code> with several important improvements:</p><ul><li>Replaces manual JS entry lists with a single HTML <code>url</code>, greatly simplifying sub-app registration.</li><li>Adds application isolation with a JS sandbox (<code>window</code> proxy/factory) and a CSS sandbox (similar to Vue&#39;s <code>scoped</code> styles).</li><li>Adds asset preloading to cache sub-app HTML, JS, and CSS ahead of time for faster startup.</li></ul><p>Let&#39;s summarize the pros and cons of this approach:</p><div class="tip custom-block"><p class="custom-block-title">Pros</p><ul><li>Automatically loads and unmounts sub-apps based on route matching.</li><li>Comprehensive sandbox design: three progressive JS sandboxes (<code>SnapshotSandbox</code>, <code>LegacySandbox</code>, <code>ProxySandbox</code>) and two CSS isolation modes (<code>strictStyleIsolation</code>, <code>experimentalStyleIsolation</code>).</li><li>Route persistence across browser refresh, back, and forward navigation.</li><li>Simple cross-app communication via global injection.</li></ul></div><div class="danger custom-block"><p class="custom-block-title">Cons</p><ul><li>Route-based activation makes it hard to keep multiple sub-apps active at once or preserve sub-app state (<code>keep-alive</code>).</li><li>High adaptation cost across Webpack configuration, entry code, and routing.</li><li>CSS isolation is not 100% airtight, and proxy-based JS sandboxes can incur significant performance degradation in certain scenarios.</li><li>Cannot natively run <code>Vite</code> or other native <code>ESM</code> scripts.</li></ul></div><h2 id="the-wujie-approach" tabindex="-1">The Wujie Approach <a class="header-anchor" href="#the-wujie-approach" aria-label="Permalink to &quot;The Wujie Approach&quot;">​</a></h2><p>An intriguing discussion in a <a href="https://github.com/umijs/qiankun/issues/286" target="_blank" rel="noreferrer">qiankun GitHub issue</a> asked whether an <code>iframe</code> could be used purely as a JavaScript sandbox. That idea inspired Wujie&#39;s architecture, described in detail below.</p><h3 id="application-loading-and-js-sandbox" tabindex="-1">Application Loading and JS Sandbox <a class="header-anchor" href="#application-loading-and-js-sandbox" aria-label="Permalink to &quot;Application Loading and JS Sandbox&quot;">​</a></h3><p>Wujie injects a sub-app&#39;s JavaScript into a same-origin <code>iframe</code> created under the main app&#39;s origin. Because an <code>iframe</code> is a browser-native <code>window</code> sandbox with its own <code>history</code> and <code>location</code>, the sub-app <code>instance</code> runs completely decoupled from the main app&#39;s router and can be mounted directly inside any UI component.</p><p>This design brings key benefits:</p><div class="tip custom-block"><p class="custom-block-title">Benefits</p><ul><li><p><strong>Component-based usage</strong></p><p>No central registration or router refactoring needed — simply render a Wujie component wherever you want.</p></li><li><p><strong>Multiple active sub-apps on one page</strong></p><p>Each sub-app uses its own iframe <code>history</code>, eliminating route conflicts.</p></li><li><p><strong>Native JS sandbox without polluting the main app</strong></p><p>Nothing is added to the main app&#39;s <code>window</code>; all mutations remain confined to the <code>iframe</code>.</p></li><li><p><strong>Zero cleanup cost when switching apps</strong></p><p>Since the main app stays untouched, destroying a sub-app requires no manual global cleanup.</p></li></ul></div><h3 id="route-synchronization-mechanism" tabindex="-1">Route Synchronization Mechanism <a class="header-anchor" href="#route-synchronization-mechanism" aria-label="Permalink to &quot;Route Synchronization Mechanism&quot;">​</a></h3><p>When a sub-app calls <code>history.pushState</code> inside its <code>iframe</code>, the browser automatically records that entry in the <a href="https://html.spec.whatwg.org/multipage/history.html#joint-session-history" target="_blank" rel="noreferrer">joint session history</a> alongside the iframe&#39;s <a href="https://html.spec.whatwg.org/multipage/history.html#session-history" target="_blank" rel="noreferrer">session history</a>. As a result, browser Back and Forward buttons naturally work on the sub-app without extra plumbing.</p><p>By intercepting the iframe&#39;s <code>history.pushState</code> and <code>history.replaceState</code>, Wujie syncs the sub-app&#39;s URL into a query parameter on the main app&#39;s URL. When the browser refreshes and re-initializes the iframe, Wujie reads that query parameter back and restores the sub-app route via <code>history.replaceState</code>.</p><p>This delivers:</p><div class="tip custom-block"><p class="custom-block-title">Benefits</p><ul><li><strong>Browser refresh, back, and forward navigation all work on sub-apps.</strong></li><li><strong>Low implementation overhead without complex manual history listeners.</strong></li><li><strong>Simultaneous route synchronization even when multiple sub-apps are active at once.</strong></li></ul></div><h3 id="iframe-bridging-and-css-sandbox" tabindex="-1">iframe Bridging and CSS Sandbox <a class="header-anchor" href="#iframe-bridging-and-css-sandbox" aria-label="Permalink to &quot;iframe Bridging and CSS Sandbox&quot;">​</a></h3><p>Wujie uses <a href="https://developer.mozilla.org/en-US/docs/Web/Web_Components" target="_blank" rel="noreferrer">Web Components</a> (Shadow DOM) for style isolation. It creates a custom <code>wujie-app</code> element and renders the sub-app&#39;s complete DOM structure inside its ShadowRoot.</p><p>The sub-app&#39;s JS <code>instance</code> runs inside the <code>iframe</code>, while its DOM lives inside the Web Component mounted in the main app container. Wujie bridges the two by proxying the iframe&#39;s <code>document</code> onto the Web Component&#39;s ShadowRoot.</p><p>DOM query APIs — <code>getElementsByTagName</code>, <code>getElementsByClassName</code>, <code>getElementsByName</code>, <code>getElementById</code>, <code>querySelector</code>, <code>querySelectorAll</code>, <code>head</code>, and <code>body</code> — are all proxied to the ShadowRoot, seamlessly connecting the JS <code>instance</code> to the Web Component DOM.</p><p>When switching away from a sub-app, the <code>iframe</code> stays alive and the Web Component can also be retained in memory. When switching back, Wujie simply re-attaches the Web Component into the container, giving sub-apps Vue-like <code>keep-alive</code> behavior out of the box.</p><p>This delivers:</p><div class="tip custom-block"><p class="custom-block-title">Benefits</p><ul><li><p><strong>Native CSS sandbox</strong></p><p>True physical style isolation with zero style modifications needed in sub-apps.</p></li><li><p><strong>Native modal &amp; popup support</strong></p><p>Calls to <code>document.body.appendChild</code> and <code>insertBefore</code> are proxied directly into the Web Component, so popups render across the viewport with zero sub-app changes.</p></li><li><p><strong>Sub-app Keep-Alive</strong></p><p>Keeping both the <code>iframe</code> and the Web Component in memory preserves all internal application state.</p></li><li><p><strong>Complete DOM structure</strong></p><p>The Web Component retains the sub-app&#39;s full <code>html</code> structure so styles and selectors match natively without rewrites.</p></li></ul></div><h3 id="communication-mechanism" tabindex="-1">Communication Mechanism <a class="header-anchor" href="#communication-mechanism" aria-label="Permalink to &quot;Communication Mechanism&quot;">​</a></h3><p>Because the sub-app&#39;s <code>iframe</code> shares the same origin as the main app, cross-app communication is straightforward. Wujie provides three built-in communication mechanisms:</p><ul><li><p><strong>Props injection</strong></p><p>Sub-apps access data and callbacks injected by the main app via <code>window.$wujie.props</code>.</p></li><li><p><strong><code>window.parent</code> direct access</strong></p><p>Because the sandbox <code>iframe</code> is same-origin with the main app, sub-apps can directly communicate with the main app via <code>window.parent</code>.</p></li><li><p><strong>Decentralized <code>EventBus</code></strong></p><p>Wujie injects a shared <code>EventBus</code> instance into both the main app and all sub-apps, enabling decentralized pub/sub communication across all apps.</p></li></ul><h3 id="advantages" tabindex="-1">Advantages <a class="header-anchor" href="#advantages" aria-label="Permalink to &quot;Advantages&quot;">​</a></h3><p>Summarizing the architecture above, Wujie offers the following advantages:</p><div class="tip custom-block"><p class="custom-block-title">Advantages</p><ul><li><p><strong>Multiple active sub-apps simultaneously</strong></p><p>Activate multiple sub-apps on the same page while keeping all of their routes synchronized.</p></li><li><p><strong>Component-driven integration</strong></p><p>No app registration or router changes — mount and unmount sub-apps just like regular components.</p></li><li><p><strong>App-level Keep-Alive</strong></p><p>Enabling <a href="/doc/en/api/startApp.html#alive">Keep-Alive mode</a> preserves the entire sub-app state across route switches. Combined with <a href="/doc/en/api/preloadApp.html#exec">pre-execution</a>, it delivers an instant, SSR-like opening experience.</p></li><li><p><strong>Clean and pollution-free</strong></p><ul><li>Native JS and CSS sandboxes built on <code>iframe</code> and <code>Web Components</code>.</li><li>Native route synchronization leveraging the shared <a href="https://html.spec.whatwg.org/multipage/browsers.html#top-level-browsing-context" target="_blank" rel="noreferrer">top-level browsing context</a>.</li><li>All side effects remain confined inside the sandbox, eliminating cleanup overhead during app switches.</li></ul></li><li><p><strong>Performance and lightweight footprint</strong></p><ul><li>Near-native execution speed: code executes directly inside the iframe&#39;s <code>window</code> context instead of <code>with (proxyWindow) { code }</code>. The one-time cost of initializing an <code>iframe</code> can be hidden ahead of time using <a href="/doc/en/api/preloadApp.html">preloadApp</a>.</li><li>Compact bundle size by delegating sandboxing to native browser primitives (<code>iframe</code> + <code>Web Components</code>).</li></ul></li><li><p><strong>Ready out of the box</strong></p><p>Style isolation, routing, popups/modals, and HMR all work out of the box with minimal <a href="/doc/en/guide/start.html#sub-app-adaptation">sub-app adaptation</a>.</p></li></ul></div>',48)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
